/* Konsolenkost Shop-Widget (Artikelsuche), entpackt aus Beitragsinhalt */
(function(){var ws=document.querySelectorAll('.kk-nw');for(var i=0;i<ws.length;i++){(function(w){if(w.dataset.init){return}w.dataset.init='1';var g=w.querySelector('.kk-nw-grid');[].forEach.call(w.querySelectorAll('img[data-src]'),function(im){im.src=im.getAttribute('data-src')});var cards=[].slice.call(g.children);var st={c:'all',p:'all',s:'rec'};function up(){var n=0;var list=cards.slice();if(st.s=='asc'){list.sort(function(a,b){return a.dataset.p-b.dataset.p})}if(st.s=='desc'){list.sort(function(a,b){return b.dataset.p-a.dataset.p})}list.forEach(function(c){g.appendChild(c);var p=+c.dataset.p;var ok=true;if(st.c!='all'){if(c.dataset.c!=st.c){ok=false}}if(st.p!='all'){var r=st.p.split('-');if(p<+r[0]){ok=false}if(p>=+r[1]){ok=false}}c.style.display=ok?'flex':'none';if(ok){n++}});w.querySelector('.kk-nw-n').textContent=n+' Artikel';g.scrollLeft=0}w.querySelectorAll('button[data-f]').forEach(function(b){b.addEventListener('click',function(){st.c=b.dataset.f;w.querySelectorAll('button[data-f]').forEach(function(x){var a=x==b;x.style.background=a?'#14232d':'#fff';x.style.color=a?'#fff':'#14232d';x.style.borderColor=a?'#14232d':'#d5dde4'});up()})});w.querySelector('.kk-nw-p').addEventListener('change',function(e){st.p=e.target.value;up()});w.querySelector('.kk-nw-s').addEventListener('change',function(e){st.s=e.target.value;up()})})(ws[i])}})();
